import time
import logging
from taf.ue.plugin.mtk.exceptions import (CreatePduSessionFailure, BindUeFailure,
                                          CreateAdditionalPduSessionFailure, DataTransferInvalid,
                                          UEUSBPortNotReady, DeploymentModeInvalid, NetworkTechnologyNotSupported)
from taf.ue.plugin.mtk.data_transfer.factory import (MTKIperfDownLinkDataTransferFactory,
                                                     MTKIperfUpLinkDataTransferFactory)
from taf.ue.plugin.mtk.data_transfer.check_throughput import IperfThroughputChecker
from taf.ue.plugin.mtk.commands import WindowsSystemCmd
from taf.ue.plugin.mtk.factory import DeploymentMode
from taf.ue.plugin.mtk.mace import (ApolloMaceController, PetrusMaceController, OppoMaceController,
                                    CaymusMaceController, BollingerMaceController)
from taf.ue.plugin.mtk.flow.aid_store import AIDStore


class UE(object):

    HW_VERSION = ""

    def __init__(self, config, mace_proxy):
        self._config = config
        self._mace_proxy = mace_proxy

        self._controller = None
        self._reboot = None
        self._enable_logging = None
        self._pre_attach = None
        self._attach = None
        self._pdn = None
        self._detach = None
        self._dl_traffic_factory = None
        self._ul_traffic_factory = None
        self._deactivate_additional_pdn = None
        self._system_command = None
        self._deployment_mode = None
        self._builtin_apn = []
        self._pdn_sessions_store = {}
        self._ue_ip = None
        self._voice_call = None
        self._enable_builtin_apn_check = False

    def setup(self):
        self._controller = self._create_controller()
        self._controller.setup()
        self.ports_ready()
        self.enable_logging()
        self._create_flow()

    def _create_controller(self):
        raise NotImplementedError

    def _create_flow(self):
        self._deployment_mode = self._get_deployment_mode_for_initializing()
        self._create_flow_by_deployment_mode(self._deployment_mode)

    def _get_deployment_mode_for_initializing(self):
        capabilities = self._config["CAPABILITIES"]
        configed_deployment_modes = []
        for capability in capabilities:
            deployment_mode = self._get_deployment_mode_by_name(capability)
            if deployment_mode:
                configed_deployment_modes.append(deployment_mode)

        if len(configed_deployment_modes) == 0:
            logging.warning("there is no deployment mode in capabilities, 'SA' mode will be applied by default,"
                            "if NSA or LTE is expected, please call change_deployment_mode keyword for change.")

            return DeploymentMode.SA

        if len(configed_deployment_modes) > 1:
            logging.warning("there are more than one deployment modes in capabilities {}".format(capabilities))
            logging.warning("'SA' mode will be applied by default. if NSA or LTE is expected,"
                            "please call change_deployment_mode keyword for change")
            return DeploymentMode.SA

        logging.info("deployment mode {} will be applied for initializing".format(configed_deployment_modes[0].value))
        return configed_deployment_modes[0]

    def _get_deployment_mode_by_name(self, name):
        for deployment_mode in DeploymentMode:
            if name.upper() == deployment_mode.value.upper() and \
               name.upper() != DeploymentMode.UNKNOWN.value.upper():
                return deployment_mode
        return None

    def change_deployment_mode(self, deployment_mode):
        self._deployment_mode = self._get_deployment_mode_by_name(deployment_mode)
        if not self._deployment_mode:
            raise DeploymentModeInvalid(deployment_mode)
        self._create_flow_by_deployment_mode(self._deployment_mode)
        logging.info("changed deployment mode to {}".format(self._deployment_mode.value))

    def _create_flow_by_deployment_mode(self, deployment_mode):
        self._pre_attach = self._controller.create_pre_attach(deployment_mode)
        self._attach = self._controller.create_attach(deployment_mode)
        self._pdn = self._controller.create_pdn(deployment_mode)
        self._detach = self._controller.create_detach(deployment_mode)
        self._deactivate_additional_pdn = self._controller.create_deactivate_additional_pdn(deployment_mode)
        self._system_command = WindowsSystemCmd(executor=self._controller.get_shell_executor())

    def _is_default_pdn_in_builtin_apns(self):
        self.builtin_apns = self._controller.detect_builtin_apn()
        default_pdn_name = self._get_default_pdn_name()
        return default_pdn_name in self.builtin_apns

    @property
    def deployment_mode(self):
        return self._deployment_mode.value

    def reboot(self):
        self._reboot = self._reboot if self._reboot else self._controller.create_reboot()
        self._reboot.execute(interval=10)
        time.sleep(25)
        self._reboot.verify()
        time.sleep(10)
        logging.info("reboot UE executed successfully")

    def enable_vonr_capability(self):
        raise NotImplementedError

    def enable_edrx_setting(self, enable=True):
        # only for M60 for now
        raise NotImplementedError

    def set_nr_edrx(self, circle_length_duration, extended_paging_time_window, unsolicited_result_code=True):
        # only for M60 for now
        raise NotImplementedError

    def power_off_sim(self):
        raise NotImplementedError

    def power_on_sim(self):
        raise NotImplementedError

    def enable_logging(self):
        if not self._enable_logging:
            self._enable_logging = self._controller.create_enable_logging()
        self._enable_logging.execute()

    def pre_attach(self):
        self._pre_attach.execute()
        self._pre_attach.verify()
        time.sleep(10)
        logging.info("pre attach executed successfully")

    def refresh_mtk_log(self):
        self._mace_proxy.read_latest_ota_message()
        self._mace_proxy.read_latest_ota_message_details()
        self._mace_proxy.read_latest_systrace()
        logging.info("refresh mtk latest log")

    def set_log_start_timestamp(self):
        self._mace_proxy.set_log_collector_start_timestamp()
        logging.info("set mtk log's global start timestamp")

    def attach(self, await_time=3):
        self.register(await_time)
        try:
            self.create_default_pdn()
        except CreatePduSessionFailure as err:
            logging.warning("failed to create default pdu session {}".format(err))

    def register(self, await_time=3):
        self.refresh_mtk_log()
        self.set_log_start_timestamp()
        self._clean_pdu_session_ue_ip()
        self._attach.execute()
        time.sleep(float(await_time))

    def enable_builtin_apn_check(self, enable=True):
        self._enable_builtin_apn_check = enable

    def create_voice_call(self, name, ue_name, definition):
        raise NotImplementedError

    def connect_additional_pdn(self, pdn):
        ue_ip = self._create_pdn_session_and_get_ue_ip(pdn)

        if not ue_ip:
            raise CreateAdditionalPduSessionFailure("failed to create additional pdu session")

        logging.info("create additional pdu session, pdn={} ue ip={}".format(pdn, ue_ip))
        self._store_pdu_session_ue_ip(pdn, ue_ip)
        return ue_ip

    def switch_to_pdu_session(self, pdn_name):
        self._ue_ip = self._get_pdu_session_ue_ip(pdn_name)

    def create_default_pdn(self):
        self._create_default_pdu_session()

    def create_data_transfer(self, name, dt_definition, ute_ue, appserver, iperf_port):
        logging.info("mtk traffic: appserver={} iperf_port={}".format(appserver, iperf_port))
        logging.info("mtk traffic: configuration={}".format(self._config))

        pdn_name = self._get_pdn_from_bearer(dt_definition.bearer)

        ue_ip = self._get_pdu_session_ue_ip(pdn_name)
        if not ue_ip:
            ue_ip = self._create_pdn_session_and_get_ue_ip(pdn_name)
            self._store_pdu_session_ue_ip(pdn_name, ue_ip)

        self.switch_to_pdu_session(pdn_name)
        self._bind_ue_ip(self.ip, appserver)
        logging.info("create {} data transfer".format(dt_definition.direction))

        if not self._dl_traffic_factory:
            self._dl_traffic_factory = MTKIperfDownLinkDataTransferFactory(ute_ue)

        if not self._ul_traffic_factory:
            self._ul_traffic_factory = MTKIperfUpLinkDataTransferFactory(ute_ue)

        if dt_definition.direction == "dl":
            return self._create_downlink_traffic(name, dt_definition, appserver, iperf_port)

        if dt_definition.direction == "ul":
            return self._create_uplink_traffic(name, dt_definition, appserver, iperf_port)

        raise DataTransferInvalid("Invalid data transfer direction: {}".format(dt_definition.direction))

    def _get_pdn_from_bearer(self, bearer):
        pdn_name = bearer.bearer_identification["pdn"]
        if pdn_name not in self._config["PDN"]:
            pdn_name = self._get_default_pdn_name()
        return pdn_name

    def _create_downlink_traffic(self, name, dt_definition, appserver, iperf_port):
        return self._dl_traffic_factory.create(alias=name,
                                               dt_definition=dt_definition,
                                               configuration=self._config,
                                               appserver=appserver,
                                               iperf_port=iperf_port,
                                               throughput_checker=IperfThroughputChecker())

    def _create_uplink_traffic(self, name, dt_definition, appserver, iperf_port):
        return self._ul_traffic_factory.create(alias=name,
                                               dt_definition=dt_definition,
                                               configuration=self._config,
                                               appserver=appserver,
                                               iperf_port=iperf_port,
                                               throughput_checker=IperfThroughputChecker())

    def _create_default_pdu_session(self):
        default_pdn_name = self._get_default_pdn_name()
        ue_ip = self._get_pdu_session_ue_ip(default_pdn_name)

        if not ue_ip:
            ue_ip = self._create_pdn_session_and_get_ue_ip(default_pdn_name)
            if not ue_ip:
                raise CreatePduSessionFailure("failed to create pdu session")

            self._store_pdu_session_ue_ip(default_pdn_name, ue_ip)

        self.switch_to_pdu_session(default_pdn_name)
        logging.info("create default pdu session pdn name={} ue ip={}".format(default_pdn_name, ue_ip))
        return ue_ip

    def _get_default_pdn_name(self):
        return self._config['data_transfer']['pdn_name']

    def _create_pdn_session_and_get_ue_ip(self, pdn_name):
        self.refresh_mtk_log()
        self._pdn.execute(pdn_name=pdn_name)
        self._pdn.verify()
        return self._collect_ue_ip(pdn_name)

    def _collect_ue_ip(self, pdn_name):
        try:
            return self._controller.collect_ue_ip(self._deployment_mode, pdn_name)
        except Exception as e:
            logging.error("failed to get ue ip cause : {}".format(e))
            return None

    def _bind_ue_ip(self, ue_ip, appserver):
        if not ue_ip:
            raise BindUeFailure("no ue ip was retrieved")
        if not self._system_command.check_ip_bind(ue_ip):
            self._system_command.config_rndis(ue_ip)
        gateway = self._system_command.get_gateway(ue_ip)
        appserver_config = self._get_appserver_config(appserver)
        self._system_command.create_routine(
            dest=appserver_config['iperf_interface_ip'],
            gateway=gateway)

        if not self._system_command.check_ip_bind(ue_ip):
            raise BindUeFailure("failed to bind ue {}".format(ue_ip))

        logging.info("mtk ue bind ue ip ready")

    def _get_appserver_config(self, appserver):
        if 'APPSERVER' in self._config and appserver in self._config['APPSERVER']:
            return self._config['APPSERVER'][appserver]
        return self._config['data_transfer']['app_server']

    def disconnect_additional_pdn(self, pdn):
        self._deactivate_additional_pdn.execute(pdn_name=pdn)
        self._deactivate_additional_pdn.verify()
        self._clean_pdu_session_ue_ip(pdn)
        logging.info("disconnect additional pdn successfully")

    def detach(self):
        self._detach.execute()
        self._clean_pdu_session_ue_ip()
        logging.info("detach ue command 'AT+EFUN=0' executed successfully")

    def _store_pdu_session_ue_ip(self, pdn_name, ue_ip):
        if pdn_name and ue_ip:
            self._pdn_sessions_store[pdn_name] = ue_ip
            logging.info("pdn_name={} ue_ip={} stored".format(pdn_name, ue_ip))
        else:
            logging.warning("pdn_name={} or ue_ip={} is empty, not stored".format(pdn_name, ue_ip))

    def _get_pdu_session_ue_ip(self, pdn_name):
        return self._pdn_sessions_store.get(pdn_name, "")

    def _clean_pdu_session_ue_ip(self, pdn_name=None):
        if pdn_name in self._pdn_sessions_store:
            self._pdn_sessions_store.pop(pdn_name)
        elif pdn_name is None:
            self._pdn_sessions_store = {}
        else:
            logging.warning("{} not in store".format(pdn_name))

    @property
    def ip(self):
        return self._ue_ip

    def teardown(self):
        pass

    def get_ue_info(self):
        return {'IP': self._ue_ip,
                'IPS': self._pdn_sessions_store}

    def ports_ready(self):
        result = self._controller.ports_ready()
        if not result:
            raise UEUSBPortNotReady("ports is not ready")

    def lock_cell(self, network_technology, arfcn, pci=None):
        if network_technology.lower() == "lte":
            self._controller.lock_lte_cell(arfcn, pci)
        elif network_technology.lower() == "nr":
            self._controller.lock_nr_cell(arfcn, pci)
        else:
            raise NetworkTechnologyNotSupported(network_technology)

    def unlock_cell(self, network_technology, arfcn, pci=None):
        if network_technology.lower() == "lte":
            self._controller.unlock_lte_cell(arfcn, pci)
        elif network_technology.lower() == "nr":
            self._controller.unlock_nr_cell(arfcn, pci)
        else:
            raise NetworkTechnologyNotSupported(network_technology)


class Apollo(UE):

    HW_VERSION = ["MT6297", "MT6298"]

    def __init__(self, config, mace_proxy):
        super(Apollo, self).__init__(config, mace_proxy)

    def _create_controller(self):
        return ApolloMaceController(self._config, self._mace_proxy)

    def attach(self, await_time=3):
        ue_ip = self.register(await_time)
        if not ue_ip:
            try:
                self.create_default_pdn()
                logging.info("create default pdu session by 'AT+CGDCONT' and 'AT+CGACT' successfully.")
            except CreatePduSessionFailure as err:
                logging.warning("failed to create default pdu session {}".format(err))
        logging.info("attach ue command 'AT+EFUN=1' executed successfully")

    def register(self, await_time=3):
        super(Apollo, self).register(await_time)
        if self._is_default_pdn_in_builtin_apns() or self._enable_builtin_apn_check:
            ue_ip = self._get_and_store_ue_ip()
            if not ue_ip:
                logging.info("There is no default pdu session created along with register.")
            return ue_ip
        return None

    def _get_and_store_ue_ip(self):
        default_pdn_name = self._get_default_pdn_name()
        ue_ip = self._collect_ue_ip(default_pdn_name)
        if ue_ip:
            self._store_pdu_session_ue_ip(default_pdn_name, ue_ip)
        return ue_ip


class Petrus(UE):

    HW_VERSION = ["MT6885", "MT6893"]

    def __init__(self, config, mace_proxy):
        super(Petrus, self).__init__(config, mace_proxy)
        self._voice_call = None

    def _get_deployment_mode_by_name(self, name):
        self._deployment_mode = super(Petrus, self)._get_deployment_mode_by_name(name)
        if self._deployment_mode == DeploymentMode.LTE:
            raise DeploymentModeInvalid("LTE mode is not supported in Petrus, please contact MTK support")
        return self._deployment_mode

    def _create_controller(self):
        return PetrusMaceController(self._config, self._mace_proxy)

    def reboot(self):
        self._mace_proxy.run_shell_command(self._get_adb_reboot_cmd())
        time.sleep(60)

        self.ports_ready()
        logging.info("reboot UE executed successfully")

    def _get_adb_reboot_cmd(self):
        serial_number = self._config.get('serial_number', "")
        reboot_command = "adb {} reboot".format("-s {}".format(serial_number) if serial_number else "")
        logging.info("reboot UE with command: {}".format(reboot_command))
        return reboot_command

    def enable_vonr_capability(self):
        self._controller.enable_vonr_capability()

    def power_off_sim(self):
        self._controller.power_off_sim()

    def power_on_sim(self):
        self._controller.power_on_sim()

    def overheating(self, oh_op, cc_dl, cc_ul, bw_fr1_dl, bw_fr1_ul, bw_fr2_dl, bw_fr2_ul,
                    mimo_fr1_dl, mimo_fr2_dl, mimo_fr1_ul, mimo_fr2_ul):
        self._controller.overheating(oh_op, cc_dl, cc_ul, bw_fr1_dl, bw_fr1_ul, bw_fr2_dl, bw_fr2_ul,
                                     mimo_fr1_dl, mimo_fr2_dl, mimo_fr1_ul, mimo_fr2_ul)

    def create_voice_call(self, name, ue_name, definition):
        self._voice_call = self._controller.create_voice_call(self._deployment_mode, name, ue_name, definition)
        return self._voice_call

    def attach(self, await_time=3):
        ue_ip = self.register(await_time)
        if not ue_ip:
            try:
                self.create_default_pdn()
                logging.info("create default pdu session by ‘AT+EAPNACT’ successfully.")
            except CreatePduSessionFailure as err:
                logging.warning("failed to create default pdu session {}".format(err))
        logging.info("attach ue command 'AT+EFUN=1' executed successfully")

    def register(self, await_time=3):
        AIDStore().init_store()
        super(Petrus, self).register(await_time)
        if self._is_default_pdn_in_builtin_apns() or self._enable_builtin_apn_check:
            ue_ip = self._get_ue_ip_and_add_ip_route_rule()
            if not ue_ip:
                logging.info("There is no default pdu session created along with register.")
            return ue_ip
        return None

    def _get_ue_ip_and_add_ip_route_rule(self):
        default_pdn_name = self._get_default_pdn_name()
        ue_ip = self._collect_ue_ip(default_pdn_name)
        if ue_ip:
            self._store_ue_ip_and_add_ip_route_rule(default_pdn_name, ue_ip)
        return ue_ip

    def _store_ue_ip_and_add_ip_route_rule(self, pdn_name, ue_ip):
        self._store_pdu_session_ue_ip(pdn_name, ue_ip)
        self._add_ip_route_rule(ue_ip)

    def _create_downlink_traffic(self, name, dt_definition, appserver, iperf_port):
        return self._dl_traffic_factory.create(alias=name,
                                               dt_definition=dt_definition,
                                               configuration=self._config,
                                               appserver=appserver,
                                               iperf_port=iperf_port,
                                               throughput_checker=IperfThroughputChecker(),
                                               is_server_adb_shell=True)

    def _create_uplink_traffic(self, name, dt_definition, appserver, iperf_port):
        return self._ul_traffic_factory.create(alias=name,
                                               dt_definition=dt_definition,
                                               configuration=self._config,
                                               appserver=appserver,
                                               iperf_port=iperf_port,
                                               throughput_checker=IperfThroughputChecker(),
                                               is_client_adb_shell=True)

    def _bind_ue_ip(self, ue_ip, appserver):
        pass

    def _clean_ip_route_rules(self):
        self._controller.clean_ip_route_rules()

    def _create_pdn_session_and_get_ue_ip(self, pdn_name):
        ue_ip = super(Petrus, self)._create_pdn_session_and_get_ue_ip(pdn_name)
        self._detect_aid_and_store(pdn_name)
        self._add_ip_route_rule(ue_ip)
        return ue_ip

    def _add_ip_route_rule(self, ue_ip):
        self._controller.add_ip_route_rule(ue_ip)

    def _detect_aid_and_store(self, pdn_name):
        aid = self._controller.detect_aid(pdn_name)
        AIDStore().store_aid(pdn_name, int(aid))

    def detach(self):
        AIDStore().init_store()
        super(Petrus, self).detach()

    def teardown(self):
        self._clean_ip_route_rules()


