class Oppo(Petrus):

    HW_VERSION = "OPPO"

    def __init__(self, config, mace_proxy):
        super(Oppo, self).__init__(config, mace_proxy)

    def reboot(self):
        self._mace_proxy.run_shell_command("adb reboot")
        time.sleep(60)

        self.ports_ready()
        logging.info("reboot UE executed successfully")
        self._mace_proxy._setup()
        time.sleep(5)

    def _create_controller(self):
        return OppoMaceController(self._config, self._mace_proxy)

    def _create_pdn_session_and_get_ue_ip(self, pdn_name):
        logging.info("oppo just use default pdn which is setup at attach steps")
        return self._collect_ue_ip(pdn_name)
